// A photo of the person behind a chart (owner 2026-11-25: "a picture for people ... so that I can see the person").
//
// Which photo: server/chart-photos.json, GENERATED by `node tools/people/photos.mjs` (never hand-edit): the person's
// own picture in Wikidata, kept only when exactly one Wikidata human with that name was born on that birth date.
// The file lives on Wikimedia Commons (free licences); its maker and licence are shown under the photo.
//
// The picture itself: fetched from Commons the first time a phone asks, shrunk to 480 px wide JPEG and kept in
// data/photos/ for good, so Commons is asked once per person, ever. Only a file named in the seed can be fetched;
// nothing about the owner is sent. Every fetch is recorded for the snapshot (PHOTOS).
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import sharp from 'sharp';
import { keyOf } from './people.js';

const UA = 'chart-vault-photos/1.0 (personal numerology app; one fetch per person)';
const CALLS = [];
const note = (entry) => { CALLS.push({ at: new Date().toISOString(), ...entry }); if (CALLS.length > 20) CALLS.shift(); };

export function loadPhotoSeed() {
  try { return JSON.parse(fs.readFileSync(new URL('./chart-photos.json', import.meta.url), 'utf8')); } catch { return []; }
}
const SEED = loadPhotoSeed();
// The cached file's name changes when the seed points at another picture, so an old copy is never shown.
const idOf = (e) => `${e.qid}-${crypto.createHash('sha1').update(e.file).digest('hex').slice(0, 8)}`;
let byTitle = null, byId = null;
function index() {
  if (!byTitle) {
    byTitle = new Map(); byId = new Map();
    for (const e of SEED) if (e && /^Q\d+$/.test(e.qid) && e.file && e.title) { const x = { ...e, id: idOf(e) }; byTitle.set(keyOf(e.title), x); byId.set(x.id, x); }
  }
}

// What the screen needs for one person: where to load it, and the credit line Commons asks for.
export function photoFor(title) {
  index();
  const e = byTitle.get(keyOf(title));
  if (!e) return null;
  return { url: `/api/photos/${e.id}.jpg`, credit: e.credit || null, license: e.license || null, license_url: e.license_url || null,
    page: `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(e.file.replace(/ /g, '_'))}` };
}

const inflight = new Map();
// The file on disk for a photo id, fetching it the first time. null = not a known photo. Throws when Commons fails.
export async function photoFile(dir, id, { fetchFn = fetch } = {}) {
  index();
  const e = byId.get(id);
  if (!e) return null;
  const file = path.join(dir, `${e.id}.jpg`);
  if (fs.existsSync(file)) return file;
  if (!inflight.has(e.id)) {
    inflight.set(e.id, (async () => {
      const url = `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(e.file.replace(/ /g, '_'))}?width=600`;
      const t0 = Date.now(), seconds = () => Math.round((Date.now() - t0) / 100) / 10;
      try {
        const res = await fetchFn(url, { headers: { 'User-Agent': UA }, redirect: 'follow', signal: AbortSignal.timeout(30_000) });
        if (!res.ok) throw new Error(`Commons answered ${res.status}`);
        const buf = Buffer.from(await res.arrayBuffer());
        if (buf.length > 15 * 1024 * 1024) throw new Error('picture too big');
        const jpg = await sharp(buf).rotate().resize({ width: 480, withoutEnlargement: true }).flatten({ background: '#ffffff' }).jpeg({ quality: 82, mozjpeg: true }).toBuffer();
        fs.mkdirSync(dir, { recursive: true });
        const tmp = `${file}.${process.pid}.tmp`;
        fs.writeFileSync(tmp, jpg); fs.renameSync(tmp, file);
        note({ what: e.title, ok: true, status: res.status, seconds: seconds(), bytes: jpg.length });
        return file;
      } catch (err) {
        note({ what: e.title, ok: false, status: null, seconds: seconds(), error: String(err.message).slice(0, 200) });
        throw err;
      } finally { inflight.delete(e.id); }
    })());
  }
  return inflight.get(e.id);
}

export function photosReport(dir) {
  index();
  let cached = 0;
  try { cached = fs.readdirSync(dir).filter((f) => f.endsWith('.jpg')).length; } catch { /* none yet */ }
  const lines = [`PHOTOS (server/photos.js; Wikimedia Commons, free; seed server/chart-photos.json from tools/people/photos.mjs)`,
    `people with a photo ${byTitle.size}   fetched and kept on this server ${cached}`];
  for (const c of CALLS.slice().reverse()) lines.push(`  ${c.at} ${c.ok ? 'ok' : 'FAILED'} ${c.what} ${c.status ?? '-'} ${c.seconds}s${c.error ? ` ${c.error}` : ''}`);
  return lines;
}
